{
  "status": "SUPPORTED",
  "task_summary": "Set up two refreshment spots near the seating and ensure the remote is easily reachable.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "A surface arrangement holding refreshments for one person.",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "table",
          "side_table",
          "coffee_table"
        ],
        "required_properties": [
          "holds_drinks",
          "holds_snacks"
        ]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "A device used to operate the television.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "remote_control",
          "tablet"
        ],
        "required_properties": [
          "operates_tv"
        ]
      },
      {
        "id": "seating_area",
        "entity_kind": "REGION",
        "function": "The location where people sit to watch television.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "armchair",
          "sofa"
        ],
        "required_properties": [
          "supports_sitter"
        ]
      }
    ],
    "functional_relations": [
      {
        "id": "refreshment_near_seating",
        "relation": "spatial_proximity",
        "participant_roles": [
          "refreshment_setting",
          "seating_area"
        ],
        "required": true
      },
      {
        "id": "control_accessible",
        "relation": "accessibility",
        "participant_roles": [
          "entertainment_control",
          "seating_area"
        ],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "prepare_refreshments",
        "operation": "arrange_refreshment_setting",
        "participant_roles": [
          "refreshment_setting"
        , "seating_area"
        ],
        "operation_count": 2
      },
      {
        "id": "move_control",
        "operation": "place_entertainment_control",
        "participant_roles": [
          "entertainment_control",
          "seating_area"
        ],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "refreshment_setting": [
        {
          "label": "large_desk",
          "visual_description": "Wooden table in foreground with cups and plates already on it."
        },
        {
          "label": "coffee_table",
          "visual_description": "Low table in center of room, currently empty."
        },
        {
          "label": "side_tables",
          "visual_description": "Two small wooden tables next to the armchairs."
        }
      ],
      "entertainment_control": [
        {
          "label": "remote_on_desk",
          "visual_description": "Black rectangular object sitting on the large desk."
        }
      ],
      "seating_area": [
        {
          "label": "armchairs",
          "visual_description": "Two black cushioned chairs facing the television."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "large_desk_surface",
        "label": "Large desk",
        "visual_description": "Foreground table with items.",
        "reason": "Currently holds the control and some refreshments; may need rearrangement."
      },
      {
        "id": "coffee_table_surface",
        "label": "Coffee table",
        "visual_description": "Central low table.",
        "reason": "Empty surface suitable for a second refreshment setting."
      },
      {
        "id": "side_table_surfaces",
        "label": "Side tables",
        "visual_description": "Tables flanking the chairs.",
        "reason": "Suitable surfaces for refreshment settings."
      }
    ],
    "inspection_order": [
      "large_desk_surface",
      "coffee_table_surface",
      "side_table_surfaces"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
